(function () {
  const LOGO_PATH = '/image/school logo.jpg';
  const LOGO_DATA_URL = "data:image/jpeg;base64,";

  if (typeof window !== 'undefined') {
    window.SCHOOL_LOGO_DATA_URL = LOGO_DATA_URL;
    window.SCHOOL_LOGO_URL = LOGO_DATA_URL;
    window.getSchoolLogoUrl = function () {
      return window.SCHOOL_LOGO_DATA_URL || (document.querySelector('[data-school-logo]') ? document.querySelector('[data-school-logo]').src : LOGO_PATH);
    };
  }

  function applyLogo() {
    const logoEls = document.querySelectorAll('[data-school-logo]');
    if (!logoEls.length) return;
    logoEls.forEach(function (el) {
      el.src = LOGO_DATA_URL;
      if (!el.getAttribute('alt')) {
        el.setAttribute('alt', 'Amala Higher Secondary School Logo');
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', applyLogo);
  } else {
    applyLogo();
  }
})();
